cd ~/Downloads && python3 - <<'EOF'
import os, shutil

DOWNLOADS = os.path.expanduser("~/Downloads")
TARGET_FOLDERS = {"Plantas","Finanzas","Automatizacion","Diseño_Fuentes","Software","Multimedia","Documentos"}

IMAGE_EXT = {".jpg",".jpeg",".png",".webp",".heic",".gif",".bmp",".tiff",".tif",".svg"}
DOC_EXT   = {".pdf",".docx",".doc",".xlsx",".xls",".pptx",".pages",".numbers",
             ".key",".csv",".txt",".html",".htm",".ics",".cgi",".enc",".pfx",
             ".pem",".zip",".7z",".rar",".tar",".gz",".md"}
VIDEO_EXT = {".mov",".mp4",".avi",".mkv",".m4v",".webm"}

moved_img, moved_doc, moved_vid, rest = 0,0,0,[]

for item in sorted(os.listdir(DOWNLOADS)):
    if item in TARGET_FOLDERS or item == "organize_downloads.py":
        continue
    if item.startswith("."):
        continue

    src = os.path.join(DOWNLOADS, item)
    is_dir = os.path.isdir(src)
    ext = os.path.splitext(item)[1].lower()

    if not is_dir and ext in VIDEO_EXT:
        dest_folder = "Multimedia"
    elif not is_dir and ext in IMAGE_EXT:
        dest_folder = "Multimedia"
    elif not is_dir and ext in DOC_EXT:
        dest_folder = "Documentos"
    elif is_dir:
        dest_folder = "Documentos"
    else:
        rest.append(item)
        continue

    dest_dir = os.path.join(DOWNLOADS, dest_folder)
    dest = os.path.join(dest_dir, item)
    if os.path.exists(dest):
        base, e = os.path.splitext(item)
        c = 1
        while os.path.exists(dest):
            dest = os.path.join(dest_dir, f"{base}_{c}{e}")
            c += 1
    shutil.move(src, dest)
    if dest_folder == "Multimedia":
        moved_img += 1
    elif dest_folder == "Documentos":
        moved_doc += 1

print(f"Multimedia (fotos/videos extra): +{moved_img}")
print(f"Documentos (docs extra):         +{moved_doc}")
if rest:
    print(f"\nAún sin clasificar ({len(rest)}):")
    for r in rest:
        print(f"  {r}")
EOF
